class CampaignCompiler:
    __slots__ = ("campaign", "types", "expr_compiler", "modules",
                 "pipes_by_target", "graph", "plans", "plans_by_entry",
                 "machine")

    def __init__(self, campaign):
        self.campaign = campaign
        self.types = TypeSystem(campaign["types"])
        self.expr_compiler = ExprCompiler(self.types)

        modules = {}
        predicate_cache = {}
        for raw in campaign["modules"]:
            params = [(parameter_name, self.types.get(type_name))
                      for parameter_name, type_name in raw["params"]]
            result_name, result_type_name = raw["result"]
            requires_raw = raw.get("requires")
            if requires_raw is None:
                requires = None
            else:
                key = structural_key(requires_raw)
                requires = predicate_cache.get(key)
                if requires is None:
                    requires = self.expr_compiler.compile(requires_raw)
                    predicate_cache[key] = requires
            modules[raw["name"]] = Module(
                raw["name"], params, result_name,
                self.types.get(result_type_name), requires)
        self.modules = modules

        graph = DependencyGraph()
        for module_name in modules:
            graph.add_node(module_name)
        for caller, callee in campaign["calls"]:
            graph.add_dependency(caller, callee)

        pipes_by_target = defaultdict(list)
        for raw in campaign["pipes"]:
            pipe = Pipe(raw["target"], raw["filter"], raw["bind"])
            pipes_by_target[pipe.target].append(pipe)
            graph.add_dependency(pipe.target, pipe.filter)
        self.pipes_by_target = pipes_by_target
        self.graph = graph

        plans = []
        plans_by_entry = {}
        for entry in campaign["entries"]:
            module_order = graph.compile_order(entry)
            type_names = _collect_declaration_names(module_order, modules)
            module = modules[entry]
            layout = compile_layout(module, bool(pipes_by_target.get(entry)))
            plan = CampaignPlan(entry, module_order, type_names,
                                layout, module)
            plans.append(plan)
            plans_by_entry[entry] = plan
        self.plans = plans
        self.plans_by_entry = plans_by_entry

        machine = campaign.get("machine")
        self.machine = (None if machine is None
                        else MachineRuntime(machine, self.expr_compiler))

    def _scope_for(self, module, values):
        return {parameter_name: (values[parameter_name], parameter_type)
                for parameter_name, parameter_type in module.params}

    def _module_predicate(self, module, values):
        if module.requires is None:
            return True
        scope = self._scope_for(module, values)
        return bool(module.requires.eval([scope])[0])

    def _filters_accept(self, target_name, target_values):
        # Filter chains may be much deeper than Python's default recursion
        # limit, so acceptance is evaluated with an explicit depth-first stack.
        # Each frame is (target module, its parameter values, next pipe index).
        stack = [(target_name, target_values, 0)]
        while stack:
            current_target, current_values, pipe_index = stack[-1]
            pipes = self.pipes_by_target.get(current_target, ())
            if pipe_index >= len(pipes):
                stack.pop()
                continue
            stack[-1] = (current_target, current_values, pipe_index + 1)
            pipe = pipes[pipe_index]
            filter_module = self.modules[pipe.filter]
            filter_values = {}
            for parameter_name, _parameter_type in filter_module.params:
                filter_values[parameter_name] = current_values[
                    pipe.bind[parameter_name]]
            if (filter_module.requires is not None
                    and not self._module_predicate(filter_module,
                                                   filter_values)):
                return False
            if self.pipes_by_target.get(pipe.filter):
                stack.append((pipe.filter, filter_values, 0))
        return True

    def _record_for_run(self, run_index, run, corpus, corpus_indices):
        entry = run["entry"]
        plan = self.plans_by_entry.get(entry)
        if plan is None:
            return {"status": "INVALID_TEST"}
        try:
            values = decode(run["ktest"], plan.layout.expected)
        except Exception:
            return {"status": "INVALID_TEST"}

        try:
            inputs = dict(plan.layout.recover_inputs(values))
            model_result = plan.layout.recover_result(values)
        except Exception:
            return {"status": "INVALID_TEST"}

        # The attestation is checked before any filtering decision.
        try:
            filters_accept = self._filters_accept(entry, inputs)
            entry_predicate = self._module_predicate(plan.module, inputs)
        except Exception:
            return {"status": "INVALID_TEST"}

        if plan.layout.flag is not None:
            flag_value = values[plan.layout.flag.encode("ascii")]
            expected_flag = 0 if filters_accept else 1
            if flag_value != expected_flag:
                return {"status": "INVALID_TEST"}

        if not filters_accept or not entry_predicate:
            return {"status": "FILTERED"}

        if self.machine is not None:
            scope = self._scope_for(plan.module, inputs)
            desired_state = inputs[self.machine.state_param]
            preparation = self.machine.prepare(desired_state, scope)
            if preparation is None:
                return {"status": "UNREACHABLE"}
            preparation_commands, preparation_cost = preparation
            message = inputs[self.machine.message_param]
        else:
            preparation_commands = ()
            preparation_cost = 0
            message = None

        key = corpus_key(entry, inputs, plan.module.params)
        case_index = corpus_indices.get(key)
        if case_index is None:
            case_index = len(corpus)
            corpus_indices[key] = case_index
            if self.machine is None:
                commands = []
            else:
                commands = list(preparation_commands)
                commands.append(message)
            corpus.append({
                "entry": entry,
                "inputs": inputs,
                "cost": preparation_cost,
                "commands": commands,
                "witnesses": [run_index],
            })
            status = "READY"
        else:
            corpus[case_index]["witnesses"].append(run_index)
            status = "DUPLICATE"
        return {"status": status, "case": case_index,
                "model_result": model_result}

    def execute(self):
        records = []
        corpus = []
        corpus_indices = {}
        for run_index, run in enumerate(self.campaign["runs"]):
            records.append(self._record_for_run(
                run_index, run, corpus, corpus_indices))
        return {
            "plans": [plan.certificate() for plan in self.plans],
            "records": records,
            "corpus": corpus,
        }


def execute(campaign):
    return CampaignCompiler(campaign).execute()
